+const form = document.getElementById('contactForm');
+const fullNameInput = document.getElementById('fullName');
+const emailInput = document.getElementById('email');
+const phoneInput = document.getElementById('phone');
+const successMessage = document.getElementById('successMessage');
+
+// Validation patterns
+const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+const phonePattern = /^(\+?1[-.\s]?)?\(?(\d{3})\)?[-.\s]?(\d{3})[-.\s]?(\d{4})$/;
+
+// Validation functions
+function validateFullName(value) {
+    if (!value || value.trim().length === 0) {
+        return { valid: false, message: 'Full name is required.' };
+    }
+    if (value.trim().length < 2) {
+        return { valid: false, message: 'Full name must be at least 2 characters.' };
+    }
+    return { valid: true, message: '' };
+}
+
+function validateEmail(value) {
+    if (!value || value.trim().length === 0) {
+        return { valid: false, message: 'Email address is required.' };
+    }
+    if (!emailPattern.test(value)) {
+        return { valid: false, message: 'Please enter a valid email address.' };
+    }
+    return { valid: true, message: '' };
+}
+
+function validatePhone(value) {
+    if (!value || value.trim().length === 0) {
+        return { valid: true, message: '' };
+    }
+    if (!phonePattern.test(value)) {
+        return { valid: false, message: 'Please enter a valid phone number.' };
+    }
+    return { valid: true, message: '' };
+}
+
+// Display error or success state
+function setFieldState(input, errorElement, isValid) {
+    if (isValid) {
+        input.classList.remove('error');
+        input.classList.add('success');
+        errorElement.classList.remove('show');
+        errorElement.textContent = '';
+    } else {
+        input.classList.remove('success');
+        input.classList.add('error');
+    }
+}
+
+function displayError(input, errorElement, message) {
+    input.classList.remove('success');
+    input.classList.add('error');
+    errorElement.classList.add('show');
+    errorElement.textContent = message;
+}
+
+function clearFieldState(input, errorElement) {
+    input.classList.remove('error', 'success');
+    errorElement.classList.remove('show');
+    errorElement.textContent = '';
+}
+
+// Real-time validation
+fullNameInput.addEventListener('blur', () => {
+    const result = validateFullName(fullNameInput.value);
+    const errorElement = document.getElementById('fullName-error');
+    if (result.valid) {
+        setFieldState(fullNameInput, errorElement, true);
+    } else {
+        displayError(fullNameInput, errorElement, result.message);
+    }
+});
+
+fullNameInput.addEventListener('focus', () => {
+    clearFieldState(fullNameInput, document.getElementById('fullName-error'));
+});
+
+emailInput.addEventListener('blur', () => {
+    const result = validateEmail(emailInput.value);
+    const errorElement = document.getElementById('email-error');
+    if (result.valid) {
+        setFieldState(emailInput, errorElement, true);
+    } else {
+        displayError(emailInput, errorElement, result.message);
+    }
+});
+
+emailInput.addEventListener('focus', () => {
+    clearFieldState(emailInput, document.getElementById('email-error'));
+});
+
+phoneInput.addEventListener('blur', () => {
+    const result = validatePhone(phoneInput.value);
+    const errorElement = document.getElementById('phone-error');
+    if (result.valid) {
+        setFieldState(phoneInput, errorElement, true);
+    } else {
+        displayError(phoneInput, errorElement, result.message);
+    }
+});
+
+phoneInput.addEventListener('focus', () => {
+    clearFieldState(phoneInput, document.getElementById('phone-error'));
+});
+
+// Form submission
+form.addEventListener('submit', (e) => {
+    e.preventDefault();
+
+    // Validate all fields
+    const fullNameResult = validateFullName(fullNameInput.value);
+    const emailResult = validateEmail(emailInput.value);
+    const phoneResult = validatePhone(phoneInput.value);
+
+    const fullNameError = document.getElementById('fullName-error');
+    const emailError = document.getElementById('email-error');
+    const phoneError = document.getElementById('phone-error');
+
+    // Display validation results
+    if (!fullNameResult.valid) {
+        displayError(fullNameInput, fullNameError, fullNameResult.message);
+    } else {
+        setFieldState(fullNameInput, fullNameError, true);
+    }
+
+    if (!emailResult.valid) {
+        displayError(emailInput, emailError, emailResult.message);
+    } else {
+        setFieldState(emailInput, emailError, true);
+    }
+
+    if (!phoneResult.valid) {
+        displayError(phoneInput, phoneError, phoneResult.message);
+    } else {
+        setFieldState(phoneInput, phoneError, true);
+    }
+
+    // If all valid, show success message
+    if (fullNameResult.valid && emailResult.valid && phoneResult.valid) {
+        form.style.display = 'none';
+        successMessage.hidden = false;
+
+        // Reset form after 3 seconds
+        setTimeout(() => {
+            form.reset();
+            clearFieldState(fullNameInput, fullNameError);
+            clearFieldState(emailInput, emailError);
+            clearFieldState(phoneInput, phoneError);
+            form.style.display = 'flex';
+            successMessage.hidden = true;
+        }, 3000);
+    }
+});
+
